def main():
    w = Writer(sorted(set(FILE_FOR.values())))
    for line in TABLE.strip().splitlines():
        parts = [x.strip() for x in line.split("|")]
        kind, q = parts[0], parts[1]
        answers = dict(zip(["where", "size", "fact"], parts[2:5] + [""] * (5 - len(parts))))
